			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
