			ld (p_grow_rs), sp
			ld sp, p_grow
			jp ntc_xn
p_grow_r:		; end of grow
			ld de, (p_grow_a0_0)
			ld hl, var_grow_a_x
			ld bc, 2
			ldir
			ld de, (p_grow_a0_1)
			ld hl, var_grow_a_y
			ld bc, 2
			ldir
			ld sp, (p_grow_rs)
			jp ntc_xn
p_nogrow_c:		; call nogrow (normal)
			pop hl			; a.x
			ld de, var_nogrow_a_x
			ld bc, 2
			ldir
			pop hl			; a.y
			ld de, var_nogrow_a_y
			ld bc, 2
			ldir
			ld (p_nogrow_rs), sp
			ld sp, p_nogrow
			jp ntc_xn
p_nogrow_r:		; end of nogrow
			ld sp, (p_nogrow_rs)
			jp ntc_xn
p_setarea_c:		; call setarea (normal)
			pop hl			; bx.name
			ld (p_setarea_a0_0), hl
			ld de, var_setarea_bx_name
			ld b, 40
p_setarea_si0_0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_setarea_si0_0_e
			inc hl
			inc de
			djnz p_setarea_si0_0
			xor a
			ld (de), a
p_setarea_si0_0_e:
			pop hl			; bx.topleft.x
			ld (p_setarea_a0_1), hl
			ld de, var_setarea_bx_topleft_x
			ld bc, 2
			ldir
			pop hl			; bx.topleft.y
			ld (p_setarea_a0_2), hl
			ld de, var_setarea_bx_topleft_y
			ld bc, 2
			ldir
			pop hl			; bx.size.x
			ld (p_setarea_a0_3), hl
			ld de, var_setarea_bx_size_x
			ld bc, 2
			ldir
			pop hl			; bx.size.y
			ld (p_setarea_a0_4), hl
			ld de, var_setarea_bx_size_y
			ld bc, 2
			ldir
			pop hl			; bx.area
			ld (p_setarea_a0_5), hl
			ld de, var_setarea_bx_area
			ld bc, 4
			ldir
			ld (p_setarea_rs), sp
			ld sp, p_setarea
			jp ntc_xn
p_setarea_r:		; end of setarea
			ld de, (p_setarea_a0_0)
			ld hl, var_setarea_bx_name
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_setarea_so0_0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_setarea_so0_0_e
			inc hl
			inc de
			djnz p_setarea_so0_0
			xor a
			ld (de), a
p_setarea_so0_0_e:
			ld de, (p_setarea_a0_1)
			ld hl, var_setarea_bx_topleft_x
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_2)
			ld hl, var_setarea_bx_topleft_y
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_3)
			ld hl, var_setarea_bx_size_x
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_4)
			ld hl, var_setarea_bx_size_y
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_5)
			ld hl, var_setarea_bx_area
			ld bc, 4
			ldir
			ld sp, (p_setarea_rs)
			jp ntc_xn
p_twice2_c:		; call twice2 (normal)
			pop hl			; a.x
			ld de, var_twice2_a_x
			ld bc, 2
			ldir
			pop hl			; a.y
			ld de, var_twice2_a_y
			ld bc, 2
			ldir
			ld hl, 0
			ld (var_twice2_twice2), hl
			ld (p_twice2_rs), sp
			ld sp, p_twice2
			jp ntc_xn
p_twice2_r:		; end of twice2
			ld sp, (p_twice2_rs)
			jp ntc_xn
p_corner_c:		; call corner (normal)
			pop hl			; g() descriptor
			ld de, pa_corner_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_corner_corner), hl
			ld (p_corner_rs), sp
			ld sp, p_corner
			jp ntc_xn
p_corner_r:		; end of corner
			ld sp, (p_corner_rs)
			jp ntc_xn
p_sum2_c:		; call sum2 (normal)
			pop hl			; g() descriptor
			ld de, pa_sum2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_sum2_sum2), hl
			ld hl, 0
			ld (var_sum2_r), hl
			ld hl, 0
			ld (var_sum2_c), hl
			ld (p_sum2_rs), sp
			ld sp, p_sum2
			jp ntc_xn
p_sum2_r:		; end of sum2
			ld sp, (p_sum2_rs)
			jp ntc_xn
p_cols_c:		; call cols (normal)
			pop hl			; g() descriptor
			ld de, pa_cols_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_cols_cols), hl
			ld (p_cols_rs), sp
			ld sp, p_cols
			jp ntc_xn
p_cols_r:		; end of cols
			ld sp, (p_cols_rs)
			jp ntc_xn
p_clear2_c:		; call clear2 (normal)
			pop hl			; g() descriptor
			ld de, pa_clear2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_clear2_r), hl
			ld hl, 0
			ld (var_clear2_c), hl
			ld (p_clear2_rs), sp
			ld sp, p_clear2
			jp ntc_xn
p_clear2_r:		; end of clear2
			ld sp, (p_clear2_rs)
			jp ntc_xn

